25	/// MemoryTracker cannot throw MEMORY_LIMIT_EXCEEDED (either configured memory
26	/// limit reached or fault injected), in the following cases:
27	///
28	/// - when it is explicitly blocked with LockExceptionInThread
29	///
30	/// - when there are uncaught exceptions objects in the current thread
31	///   (to avoid std::terminate())
32	///
33	///   NOTE: that since C++11 destructor marked with noexcept by default, and
34	///   this means that any throw from destructor (that is not marked with
35	///   noexcept(false)) will cause std::terminate()
36	bool inline memoryTrackerCanThrow(VariableContext level, bool fault_injection)
37	{
38	    return !LockMemoryExceptionInThread::isBlocked(level, fault_injection) && !std::uncaught_exceptions();
39	}
