124	void MemoryTracker::allocImpl(Int64 size, bool throw_if_memory_exceeded, MemoryTracker * query_tracker)
125	{
126	    if (size < 0)
127	        throw DB::Exception(DB::ErrorCodes::LOGICAL_ERROR, "Negative size ({}) is passed to MemoryTracker. It is a bug.", size);
128	
129	    if (MemoryTrackerBlockerInThread::isBlocked(level))
130	    {
131	        /// Since the MemoryTrackerBlockerInThread should respect the level, we should go to the next parent.
132	        if (auto * loaded_next = parent.load(std::memory_order_relaxed))
133	            loaded_next->allocImpl(size, throw_if_memory_exceeded,
134	                level == VariableContext::Process ? this : query_tracker);
135	        return;
136	    }
137	
138	    /** Using memory_order_relaxed means that if allocations are done simultaneously,
139	      *  we allow exception about memory limit exceeded to be thrown only on next allocation.
140	      * So, we allow over-allocations.
141	      */
142	    Int64 will_be = size + amount.fetch_add(size, std::memory_order_relaxed);
143	
144	    auto metric_loaded = metric.load(std::memory_order_relaxed);
145	    if (metric_loaded != CurrentMetrics::end())
146	        CurrentMetrics::add(metric_loaded, size);
147	
148	    Int64 current_hard_limit = hard_limit.load(std::memory_order_relaxed);
149	    Int64 current_profiler_limit = profiler_limit.load(std::memory_order_relaxed);
150	
151	    /// Cap the limit to the total_memory_tracker, since it may include some drift
152	    /// for user-level memory tracker.
153	    ///
154	    /// And since total_memory_tracker is reset to the process resident
155	    /// memory peridically (in AsynchronousMetrics::update()), any limit can be
156	    /// capped to it, to avoid possible drift.
157	    if (unlikely(current_hard_limit
158	        && will_be > current_hard_limit
159	        && level == VariableContext::User))
160	    {
161	        Int64 total_amount = total_memory_tracker.get();
162	        if (amount > total_amount)
163	        {
164	            set(total_amount);
165	            will_be = size + total_amount;
166	        }
167	    }
168	
169	    std::bernoulli_distribution fault(fault_probability);
170	    if (unlikely(fault_probability && fault(thread_local_rng)) && memoryTrackerCanThrow(level, true) && throw_if_memory_exceeded)
171	    {
172	        /// Prevent recursion. Exception::ctor -> std::string -> new[] -> MemoryTracker::alloc
173	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
174	
175	        ProfileEvents::increment(ProfileEvents::QueryMemoryLimitExceeded);
176	        const auto * description = description_ptr.load(std::memory_order_relaxed);
177	        amount.fetch_sub(size, std::memory_order_relaxed);
178	        throw DB::Exception(
179	            DB::ErrorCodes::MEMORY_LIMIT_EXCEEDED,
180	            "Memory tracker{}{}: fault injected. Would use {} (attempt to allocate chunk of {} bytes), maximum: {}",
181	            description ? " " : "",
182	            description ? description : "",
183	            formatReadableSizeWithBinarySuffix(will_be),
184	            size,
185	            formatReadableSizeWithBinarySuffix(current_hard_limit));
186	    }
187	
188	
189	    bool allocation_traced = false;
190	    if (unlikely(current_profiler_limit && will_be > current_profiler_limit))
191	    {
192	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
193	        DB::TraceCollector::collect(DB::TraceType::Memory, StackTrace(), size);
194	        setOrRaiseProfilerLimit((will_be + profiler_step - 1) / profiler_step * profiler_step);
195	        allocation_traced = true;
196	    }
197	
198	    std::bernoulli_distribution sample(sample_probability);
199	    if (unlikely(sample_probability && sample(thread_local_rng)))
200	    {
201	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
202	        DB::TraceCollector::collect(DB::TraceType::MemorySample, StackTrace(), size);
203	        allocation_traced = true;
204	    }
205	
206	    if (unlikely(current_hard_limit && will_be > current_hard_limit) && memoryTrackerCanThrow(level, false) && throw_if_memory_exceeded)
207	    {
208	        OvercommitResult overcommit_result = OvercommitResult::NONE;
209	        if (auto * overcommit_tracker_ptr = overcommit_tracker.load(std::memory_order_relaxed); overcommit_tracker_ptr != nullptr && query_tracker != nullptr)
210	            overcommit_result = overcommit_tracker_ptr->needToStopQuery(query_tracker, size);
211	
212	        if (overcommit_result != OvercommitResult::MEMORY_FREED)
213	        {
214	            /// Prevent recursion. Exception::ctor -> std::string -> new[] -> MemoryTracker::alloc
215	            MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
216	            ProfileEvents::increment(ProfileEvents::QueryMemoryLimitExceeded);
217	            const auto * description = description_ptr.load(std::memory_order_relaxed);
218	            throw DB::Exception(
219	                DB::ErrorCodes::MEMORY_LIMIT_EXCEEDED,
220	                "Memory limit{}{} exceeded: would use {} (attempt to allocate chunk of {} bytes), maximum: {}. OvercommitTracker decision: {}.",
221	                description ? " " : "",
222	                description ? description : "",
223	                formatReadableSizeWithBinarySuffix(will_be),
224	                size,
225	                formatReadableSizeWithBinarySuffix(current_hard_limit),
226	                toDescription(overcommit_result));
227	        }
228	        else
229	        {
230	            // If OvercommitTracker::needToStopQuery returned false, it guarantees that enough memory is freed.
231	            // This memory is already counted in variable `amount` in the moment of `will_be` initialization.
232	            // Now we just need to update value stored in `will_be`, because it should have changed.
233	            will_be = amount.load(std::memory_order_relaxed);
234	        }
235	    }
236	
237	    bool peak_updated;
238	    if (throw_if_memory_exceeded)
239	    {
240	        /// Prevent recursion. Exception::ctor -> std::string -> new[] -> MemoryTracker::alloc
241	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
242	        bool log_memory_usage = true;
243	        peak_updated = updatePeak(will_be, log_memory_usage);
244	    }
245	    else
246	    {
247	        bool log_memory_usage = false;
248	        peak_updated = updatePeak(will_be, log_memory_usage);
249	    }
250	
251	    if (peak_updated && allocation_traced)
252	    {
253	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
254	        DB::TraceCollector::collect(DB::TraceType::MemoryPeak, StackTrace(), will_be);
255	    }
256	
257	    if (auto * loaded_next = parent.load(std::memory_order_relaxed))
258	        loaded_next->allocImpl(size, throw_if_memory_exceeded,
259	            level == VariableContext::Process ? this : query_tracker);
260	}
