270	bool MemoryTracker::updatePeak(Int64 will_be, bool log_memory_usage)
271	{
272	    auto peak_old = peak.load(std::memory_order_relaxed);
273	    if (will_be > peak_old)        /// Races doesn't matter. Could rewrite with CAS, but not worth.
274	    {
275	        peak.store(will_be, std::memory_order_relaxed);
276	
277	        if (log_memory_usage && (level == VariableContext::Process || level == VariableContext::Global)
278	            && will_be / log_peak_memory_usage_every > peak_old / log_peak_memory_usage_every)
279	            logMemoryUsage(will_be);
280	
281	        return true;
282	    }
283	    return false;
284	}
