287	void MemoryTracker::free(Int64 size)
288	{
289	    if (MemoryTrackerBlockerInThread::isBlocked(level))
290	    {
291	        /// Since the MemoryTrackerBlockerInThread should respect the level, we should go to the next parent.
292	        if (auto * loaded_next = parent.load(std::memory_order_relaxed))
293	            loaded_next->free(size);
294	        return;
295	    }
296	
297	    std::bernoulli_distribution sample(sample_probability);
298	    if (unlikely(sample_probability && sample(thread_local_rng)))
299	    {
300	        MemoryTrackerBlockerInThread untrack_lock(VariableContext::Global);
301	        DB::TraceCollector::collect(DB::TraceType::MemorySample, StackTrace(), -size);
302	    }
303	
304	    Int64 accounted_size = size;
305	    if (level == VariableContext::Thread)
306	    {
307	        /// Could become negative if memory allocated in this thread is freed in another one
308	        amount.fetch_sub(accounted_size, std::memory_order_relaxed);
309	    }
310	    else
311	    {
312	        Int64 new_amount = amount.fetch_sub(accounted_size, std::memory_order_relaxed) - accounted_size;
313	
314	        /** Sometimes, query could free some data, that was allocated outside of query context.
315	          * Example: cache eviction.
316	          * To avoid negative memory usage, we "saturate" amount.
317	          * Memory usage will be calculated with some error.
318	          * NOTE: The code is not atomic. Not worth to fix.
319	          */
320	        if (unlikely(new_amount < 0))
321	        {
322	            amount.fetch_sub(new_amount);
323	            accounted_size += new_amount;
324	        }
325	    }
326	    if (auto * overcommit_tracker_ptr = overcommit_tracker.load(std::memory_order_relaxed))
327	        overcommit_tracker_ptr->tryContinueQueryExecutionAfterFree(accounted_size);
328	
329	    if (auto * loaded_next = parent.load(std::memory_order_relaxed))
330	        loaded_next->free(size);
331	
332	    auto metric_loaded = metric.load(std::memory_order_relaxed);
333	    if (metric_loaded != CurrentMetrics::end())
334	        CurrentMetrics::sub(metric_loaded, accounted_size);
335	}
