397	void MemoryTracker::setOrRaiseHardLimit(Int64 value)
398	{
399	    /// This is just atomic set to maximum.
400	    Int64 old_value = hard_limit.load(std::memory_order_relaxed);
401	    while ((value == 0 || old_value < value) && !hard_limit.compare_exchange_weak(old_value, value))
402	        ;
403	}
404	
