406	void MemoryTracker::setOrRaiseProfilerLimit(Int64 value)
407	{
408	    Int64 old_value = profiler_limit.load(std::memory_order_relaxed);
409	    while ((value == 0 || old_value < value) && !profiler_limit.compare_exchange_weak(old_value, value))
410	        ;
411	}

